// Decide which follow-up (if any) is due for each open quote.
// Double idempotency guard: status must be 'open' AND the step's flag must be empty.
const cfg = $('⚙️ Your settings').first().json;
// Parse YYYY-MM-DD as LOCAL midnight — new Date('YYYY-MM-DD') is UTC midnight,
// which lands on the previous calendar day in UTC-minus timezones (US/Canada)
// and silently shifts every day count up by one.
const parseLocalDate = (raw) => {
  const m = String(raw || '').trim().match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  return m ? new Date(+m[1], +m[2] - 1, +m[3]) : new Date(String(raw || '').trim());
};
const today = new Date();
today.setHours(0, 0, 0, 0);
const due = [];

for (const item of $('Read all quotes').all()) {
  const q = item.json;
  if (String(q.status || '').trim().toLowerCase() !== 'open') continue;
  if (!q.sent_date || !q.customer_email) continue;

  const sent = parseLocalDate(q.sent_date);
  if (isNaN(sent.getTime())) continue;
  sent.setHours(0, 0, 0, 0);
  const days = Math.round((today - sent) / 86400000); // round: both are local midnights; floor undercounts by one across a DST spring-forward

  let step = null;
  if (days >= cfg.day3Offset && !q.followup_3) step = 3;
  else if (days >= cfg.day2Offset && !q.followup_2) step = 2;
  else if (days >= cfg.day1Offset && !q.followup_1) step = 1;
  if (!step) continue;

  const fill = (t) => String(t)
    .replaceAll('{customer_name}', q.customer_name || 'there')
    .replaceAll('{quote_amount}', q.quote_amount || 'your project')
    .replaceAll('{your_name}', cfg.yourName)
    .replaceAll('{business_name}', cfg.businessName)
    .replaceAll('{your_phone}', cfg.yourPhone);

  due.push({
    json: {
      quote_id: q.quote_id,
      customer_email: q.customer_email,
      step,
      subject: fill(cfg['subject' + step]),
      body: fill(cfg['body' + step]),
      flag_column: 'followup_' + step,
    },
  });
}

return due;

// Fix the dynamic column name into a concrete key before writing back —
// the Sheets node maps plain input fields to columns; expression keys are not evaluated.
const q = $('One quote at a time').item.json;
const stamp = { quote_id: q.quote_id };
stamp[q.flag_column] = $now.toFormat('yyyy-MM-dd');
return [{ json: stamp }];
